import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static class Matrix extends ArrayList<ArrayList<Integer>> {
        public Matrix(int rows, int cols) {
            super();
            for (int i = 0; i < rows; i++) {
                ArrayList<Integer> row = new ArrayList<>();
                for (int j = 0; j < cols; j++) {
                    row.add(0);
                }
                this.add(row);
            }
        }

        public static Matrix identity(int size) {
            Matrix id = new Matrix(size, size);
            for (int i = 0; i < size; i++) {
                id.get(i).set(i, 1);
            }
            return id;
        }
    }

    static Matrix rotate(Matrix mat, int shift) {
        int size = mat.size() - 1;
        shift = (size - shift) % size;
        Matrix result = new Matrix(mat.size(), mat.get(0).size());
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                result.get(i).set(j, mat.get((i + shift) % size).get((j + shift) % size));
            }
        }
        for (int j = 0; j < size; j++) {
            result.get(size).set(j, mat.get(size).get((j + shift) % size));
        }
        return result;
    }

    static Matrix multiply(Matrix a, Matrix b) {
        int n = a.size();
        int k = a.get(0).size();
        int m = b.get(0).size();

        Matrix res = new Matrix(n, m);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                long sum = 0;
                for (int l = 0; l < k; l++) {
                    sum += (long) a.get(i).get(l) * b.get(l).get(j);
                }
                res.get(i).set(j, (int) (sum % MOD));
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        int max_depth = 0;
        long temp = n;
        while (temp != 0) {
            max_depth++;
            temp /= k;
        }

        List<Matrix> dp_levels = new ArrayList<>();
        // Initialize dp_levels[0]
        Matrix base0 = new Matrix(k + 1, k + 1);
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                if (i == j || j == 0) {
                    base0.get(i).set(j, 1);
                } else {
                    base0.get(i).set(j, 0);
                }
            }
        }
        dp_levels.add(base0);

        // Identity matrix
        Matrix identity = Matrix.identity(k + 1);

        // Build dp_levels for each depth
        for (int depth = 1; depth < max_depth; depth++) {
            Matrix prev = dp_levels.get(depth - 1);
            Matrix current = identity;
            int current_x = k;
            int i = 0;
            while ((1 << i) <= current_x) {
                if ((current_x & (1 << i)) != 0) {
                    current = multiply(prev, rotate(current, 1 << i));
                    current_x ^= (1 << i);
                }
                prev = multiply(prev, rotate(prev, 1 << i));
                i++;
            }
            dp_levels.add(current);
        }

        // Initialize start_base
        Matrix start_base = new Matrix(1, k + 1);
        start_base.get(0).set(k, 1);

        long val = n;
        List<Integer> digits = new ArrayList<>();
        while (val != 0) {
            digits.add((int) (val % k));
            val /= k;
        }

        int shift_idx = 0;
        for (int idx = digits.size() - 1; idx >= 0; idx--) {
            int rem = digits.get(idx);
            for (int it = 0; it < rem; it++, shift_idx = (shift_idx + 1) % k) {
                start_base = multiply(start_base, rotate(dp_levels.get(idx), shift_idx));
            }
        }

        int total_res = 0;
        for (int i = 0; i <= k; i++) {
            total_res = (total_res + start_base.get(0).get(i)) % (int) MOD;
        }

        System.out.println(total_res);
        sc.close();
    }
}
